export { accountsKeys };

/** List all accounts */
export function useListAccounts(query?: { limit?: number }, options?: Omit<UseQueryOptions<Accounts, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: accountsKeys.list(query),
    queryFn: async () => {
      const result = await api.accounts.listAccounts(query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}

